const cfg = $('Config').first().json;
const url = cfg.chatwoot_url + '/api/v1/accounts/' + cfg.account_id + '/conversations?status=open,resolved,snoozed&sort=-updated_at&per_page=100';
return { url };

const c = $json.conversation || {};
const contact = c.contact || {};
const assignee = c.assignee || {};
return [{
  json: {
    conversation_id: String(c.id || ''),
    contact_id: contact.id || '',
    contact_name: contact.name || '',
    contact_email: contact.email || '',
    contact_phone: (contact.phone_number || '').replace(/\D/g, ''),
    inbox_id: String(c.inbox_id || ''),
    status: c.status || 'open',
    assignee_id: assignee.id || '',
    assignee_name: assignee.name || '',
    labels: (c.labels || []).map(l => l.title || l),
    created_at: c.created_at,
    updated_at: c.updated_at,
    messages_count: c.messages_count || 0,
    unread_count: c.unread_count || 0,
  }
}];

const c = $('Extrai Conversa').first().json;
const lead = $('Busca Lead').first()?.json;
const msgs = $('Le Mensagens').first()?.json?.messages || [];

// timestamps
const created = new Date(c.created_at);
const updated = new Date(c.updated_at);
const agora = new Date();
const dias = Math.floor((agora - updated) / (1000*60*60*24));

// primeira resposta do corretor (message_type = outgoing)
let primeira_resposta = null;
let msgs_lead = 0, msgs_corretor = 0;
for (const m of msgs) {
  if (m.message_type === 'incoming') msgs_lead++;
  else msgs_corretor++;
  if (m.message_type === 'outgoing' && !primeira_resposta) primeira_resposta = m.created_at;
}

// tempo de resposta em segundos
let tempo_resposta_s = null;
if (primeira_resposta) {
  const pr = new Date(primeira_resposta);
  tempo_resposta_s = Math.floor((pr - created) / 1000);
}

// score (0-100): urgencia + qualificacao + tempo resposta
let score = 50;  // baseline
if (lead) {
  if (lead.urgencia?.includes('imediato')) score += 20;
  else if (lead.urgencia?.includes('30')) score += 10;
  score += Math.min(lead.campos_preenchidos * 2, 20);  // max +20
}
if (tempo_resposta_s && tempo_resposta_s < 300) score += 10;  // respondeu rapido
if (msgs_lead >= 5) score += 5;  // lead engajado
score = Math.min(Math.max(score, 0), 100);

return [{
  json: {
    dias_em_aberto: dias,
    tempo_resposta_s,
    primeira_resposta,
    mensagens_lead: msgs_lead,
    mensagens_corretor: msgs_corretor,
    score: Math.round(score),
    lead_id: lead?.id,
  }
}];
